namespace NavFixture

module RecordFlows =
    type Address = { City: string; Zip: int }
    type Customer = { Name: string; Home: Address }
    type Supplier = { Name: string; Code: int }
    type Box<'T> = { Value: 'T }
    type CustomerAlias = Customer
    type Counter = { mutable Count: int }

    let explicitCustomer (customer: Customer) = customer.Name
    let explicitSupplier (supplier: Supplier) = supplier.Name

    let localAnnotation () =
        let customer: Customer = { Name = "local"; Home = { City = "London"; Zip = 1 } }
        customer.Name

    let qualifiedConstruction () =
        let customer = { Customer.Name = "qualified"; Home = { City = "Oslo"; Zip = 2 } }
        customer.Name

    let inferredConstruction () =
        let customer = { Name = "inferred"; Home = { City = "Tokyo"; Zip = 3 } }
        customer.Name

    let makeCustomer name = { Name = name; Home = { City = "Paris"; Zip = 4 } }
    let makeAnnotated name : Customer = { Name = name; Home = { City = "Bern"; Zip = 5 } }
    let returnedRecord () =
        let customer = makeCustomer "returned"
        customer.Name
    let annotatedReturn () =
        let customer = makeAnnotated "annotated"
        customer.Name
    let directReturnedRecord () = (makeCustomer "direct").Name

    let copiedRecord (customer: Customer) =
        let updated = { customer with Name = "updated" }
        updated.Name

    let aliasChain (customer: Customer) =
        let second = customer
        let third = second
        third.Name

    let typeAlias (customer: CustomerAlias) = customer.Name
    let nestedField (customer: Customer) = customer.Home.City
    let genericCustomer (box: Box<Customer>) = box.Value.Name
    let genericAddress (box: Box<Address>) = box.Value.City

    let tupleBinders ((customer: Customer), (supplier: Supplier)) =
        customer.Name, supplier.Name

    let optionBinder (input: Customer option) =
        match input with
        | Some customer -> customer.Name
        | None -> "none"

    let annotatedLambda (customers: Customer list) =
        customers |> List.map (fun (customer: Customer) -> customer.Name)

    let recordPattern ({ Name = name }: Customer) = name

    let dirtyReceiver (receiver: Customer) = receiver.Name
    let dirtyAlias (left: Customer) (right: Supplier) =
        let selected = left
        selected.Name

    let useCounter (counter: Counter) =
        counter.Count <- counter.Count + 1
        counter.Count

    module Shadowed =
        type Customer = Supplier
        let localAlias (customer: Customer) = customer.Name
        let outerAlias (customer: CustomerAlias) = customer.Name

    module OuterTypes =
        type Item = { Name: string }
    module InnerTypes =
        type Item = { Name: int }
        let local (item: Item) = item.Name
        let outer (item: OuterTypes.Item) = item.Name
